function show(plan,quiet){lastShown=plan;window.tbLastPlan=plan;results.classList.add('show');var live=plan.source==='qloo-live';el('title').textContent=plan.mode==='evening'?T('Your evening, fair to both'):T('{what} for both of you',{what:occLabel(plan)});el('subtitle').textContent=[plan.seeds[0].name+' ('+T('kind.'+plan.seeds[0].kind)+') + '+plan.seeds[1].name+' ('+T('kind.'+plan.seeds[1].kind)+')',plan.near?cap(T({k:'where.near'})):plan.city,plan.mode==='evening'?[T('from {time}',{time:plan.start}),plan.special?T('special.'+plan.special):plan.specialLabel,plan.cuisine&&cap(T('cuisine.'+plan.cuisine)),plan.mood&&cap(T('mood.'+plan.mood)),plan.budget?'$$$$'.slice(0,plan.budget):''].filter(Boolean).join(', '):''].filter(Boolean).join(' · ');el('source').className='pill'+(live?'':' sample');el('source').textContent=live?T('Live Qloo results'):T('Illustrative sample — not Qloo');var note=[plan.warningKey?T(plan.warningKey):plan.warning,plan.tip?T('Tip: {tip}',{tip:plan.special?T('tip.'+plan.special):plan.tip}):''].filter(Boolean).join(' ');el('warn').textContent=note;el('warn').className='warn'+(note?' show':'');var legend=el('legend');legend.replaceChildren();var la=text('span');var ia=text('i');ia.style.background='var(--coral)';la.append(ia,document.createTextNode(T('Driven by {name}',{name:plan.seeds[0].person?plan.seeds[0].person+' ('+plan.seeds[0].name+')':plan.seeds[0].name})));var lb=text('span');var ib=text('i');ib.style.background='var(--mint)';lb.append(ib,document.createTextNode(T('Driven by {name}',{name:plan.seeds[1].person?plan.seeds[1].person+' ('+plan.seeds[1].name+')':plan.seeds[1].name})));legend.append(la,lb);var root=el('places');root.replaceChildren();root.className=plan.mode==='evening'?'':'grid';drawSky(plan);drawRoute(plan);if(plan.mode==='evening'){plan.stops.forEach(function(stop){var sec=text('section','stop');var head=text('div','stop-head');head.append(text('span','time',stop.time),text('h4',null,T('stop.'+stop.slot)));if(stop.slot==='after')head.append(text('p','stop-note',T('A short walk from dinner.')));if(stop.slot==='show')head.append(text('p','stop-note',T('Qloo has no event listings, so check each venue’s website for tonight’s programme.')));sec.append(head);if(stop.options.length>1)sec.append(text('p','swipe-hint',T('Swipe for {n} options →',{n:stop.options.length})));var g=text('div','grid cols3');stop.options.forEach(function(pick,i){g.append(placeCard(pick,i?T('OR'):T('BEST FOR BOTH'),plan,stop))});sec.append(g);root.append(sec)})}else{plan.places.forEach(function(pick,i){root.append(placeCard(pick,i?T('OPTION {n}',{n:i+1}):T('TOP BRIDGE'),plan,null))})}var films=el('films');films.replaceChildren();(plan.films||[]).forEach(function(f){var box=text('div','film');box.dataset.option=f.id||'';var po=photo(f.image,T('Poster of {name}',{name:f.name}),'poster');if(po)box.append(po);var body=text('div','film-body');body.append(text('b',null,f.name));var info=[f.year,(f.genres||[]).join(', ')].filter(Boolean).join(' · ');if(info)body.append(text('div','film-info',info));if(f.share){body.append(bar(f.share),split(f.share,plan))}box.append(body);films.append(box)});el('filmsTitle').textContent=plan.mode==='evening'?T('Back home: a film for both'):T('Something to watch together');el('filmNote').textContent=plan.filmNoteKey?T(plan.filmNoteKey):T(plan.filmNote);el('method').textContent=plan.methodKey?T(plan.methodKey):T(plan.method);if(!quiet)results.scrollIntoView({behavior:'smooth',block:'start'})}
