async function run(ev){ev.preventDefault();notice.className='notice';results.classList.remove('show');el('steps').replaceChildren();agent.classList.add('show');var button=el('run');button.disabled=true;button.textContent=T('The agent is working…');try{var picks=[el('first').dataset.pick||null,el('second').dataset.pick||null];var profiles=[window.tbProfile?window.tbProfile():null,null];var payload=mode==='evening'?{profiles:profiles,picks:picks,first:el('first').value,second:el('second').value,city:el('city').value,lat:near&&near.lat,lon:near&&near.lon,start:el('start').value,day:['sunday','monday','tuesday','wednesday','thursday','friday','saturday'][new Date().getDay()],cuisine:el('cuisine').value,mood:mood,budget:el('budget').value,special:special}:{profiles:profiles,picks:picks,first:el('first').value,second:el('second').value,city:el('city').value,occasion:occasion};var res=await fetch(mode==='evening'?'/api/evening':'/api/plan',{method:'POST',headers:{'content-type':'application/json',accept:'application/x-ndjson'},body:JSON.stringify(payload)});if(!res.ok||!res.body){var bad=await res.json().catch(function(){return{}});throw new Error(T(bad.error||"Request failed."))}var reader=res.body.getReader(),decoder=new TextDecoder(),buffer='',done=false;while(!done){var chunk=await reader.read();if(chunk.done)break;buffer+=decoder.decode(chunk.value,{stream:true});var lines=buffer.split('\n');buffer=lines.pop();for(var i=0;i<lines.length;i++){if(!lines[i].trim())continue;var msg=JSON.parse(lines[i]);if(msg.event==='step')addStep(msg.step);else if(msg.event==='result'){show(msg.plan);done=true}else if(msg.event==='error')throw new Error(T(msg.error))}}}catch(err){notice.textContent=err.message;notice.className='notice show'}finally{button.disabled=false;button.textContent=mode==='evening'?T('Plan our evening ↗'):T('Find common ground ↗')}}
