// Suggestions for a favorite: Qloo's matches with their kind, so people pick exactly what they mean.
var KIND_ICON={destination:'✈️',film:'🎬',artist:'🎵',book:'📚',author:'✍️','TV show':'📺',podcast:'🎙️','video game':'🎮',album:'💿',brand:'🏷️',person:'👤'};
function attachSuggest(input,opts){opts=opts||{};var box=null,timer=null,items=[],active=-1,seq=0;
  function close(){if(box){box.remove();box=null}input.setAttribute('aria-expanded','false');active=-1}
  function choose(it){if(opts.onPick){input.value='';close();opts.onPick(it);return}input.value=it.name;input.dataset.pick=it.id;close();input.dispatchEvent(new Event('change'))}
  function render(){close();if(!items.length)return;box=text('div','suggest');box.setAttribute('role','listbox');items.forEach(function(it,i){var b=document.createElement('button');b.type='button';b.setAttribute('role','option');b.setAttribute('aria-selected',String(i===active));b.append(document.createTextNode((KIND_ICON[it.kind]||'⭐')+' '+it.name),text('small',null,T('kind.'+it.kind)));b.addEventListener('mousedown',function(e){e.preventDefault();choose(it)});box.append(b)});input.parentNode.append(box);input.setAttribute('aria-expanded','true')}
  input.addEventListener('input',function(){delete input.dataset.pick;clearTimeout(timer);var q=input.value.trim();if(q.length<2){items=[];close();return}timer=setTimeout(function(){var my=++seq;fetch('/api/suggest?q='+encodeURIComponent(q)+(opts.types?'&types='+opts.types.join(','):'')).then(function(r){return r.json()}).then(function(d){if(my!==seq||document.activeElement!==input)return;items=d.items||[];active=-1;if(!items.length&&opts.onEmpty)opts.onEmpty(q);render()}).catch(function(){})},250)});
  input.addEventListener('keydown',function(e){if(!box)return;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();active=(active+(e.key==='ArrowDown'?1:-1)+items.length)%items.length;render()}else if(e.key==='Enter'&&active>=0){e.preventDefault();choose(items[active])}else if(e.key==='Escape')close()});
  input.addEventListener('blur',function(){setTimeout(close,150)})}
